package net.kdt.pojavlaunch.fragments;
import android.os.Bundle;import android.view.View;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.ProgressBar;import android.widget.TextView;import android.widget.Toast;import androidx.annotation.NonNull;import androidx.annotation.Nullable;import androidx.fragment.app.Fragment;import net.kdt.pojavlaunch.PojavApplication;import net.kdt.pojavlaunch.R;import net.kdt.pojavlaunch.Tools;import net.kdt.pojavlaunch.UiMotion;import net.kdt.pojavlaunch.csclient.*;import java.util.List;
public class CsClientPickerFragment extends Fragment{public static final String TAG="CS_CLIENT_PICKER";private String mc;private boolean pack;private LinearLayout list;private ProgressBar loading;private EditText search;public CsClientPickerFragment(){super(R.layout.fragment_cs_client_picker);}@Override public void onCreate(@Nullable Bundle s){super.onCreate(s);mc=requireArguments().getString("mc");pack=requireArguments().getBoolean("pack");}@Override public void onViewCreated(@NonNull View r,@Nullable Bundle s){list=r.findViewById(R.id.csc_picker_list);loading=r.findViewById(R.id.csc_picker_loading);search=r.findViewById(R.id.csc_picker_search);((TextView)r.findViewById(R.id.csc_picker_title)).setText(pack?"Choose one modpack":"Choose mods");((TextView)r.findViewById(R.id.csc_picker_subtitle)).setText("Minecraft "+mc+" • Fabric compatible only");r.findViewById(R.id.csc_picker_back).setOnClickListener(v->back());r.findViewById(R.id.csc_picker_done).setOnClickListener(v->back());r.findViewById(R.id.csc_picker_search_go).setOnClickListener(v->load(search.getText().toString()));search.setOnEditorActionListener((v,a,e)->{load(search.getText().toString());return true;});UiMotion.pressFeedback(r.findViewById(R.id.csc_picker_back),r.findViewById(R.id.csc_picker_done),r.findViewById(R.id.csc_picker_search_go));load("");}private void load(String q){loading.setVisibility(View.VISIBLE);list.removeAllViews();PojavApplication.sExecutorService.execute(()->{try{List<CsClientCatalog.ProjectEntry>x=CsClientCatalog.search(q,mc,pack);Tools.runOnUiThread(()->{if(!isAdded())return;loading.setVisibility(View.GONE);long delay=0;for(CsClientCatalog.ProjectEntry e:x){View row=row(e);row.setAlpha(0f);row.setTranslationX(dp(12));list.addView(row);row.animate().alpha(1f).translationX(0).setStartDelay(delay).setDuration(220).start();delay+=24;}});}catch(Exception e){Tools.runOnUiThread(()->{loading.setVisibility(View.GONE);Toast.makeText(requireContext(),"Search failed",Toast.LENGTH_SHORT).show();});}});}private View row(CsClientCatalog.ProjectEntry e){LinearLayout r=new LinearLayout(requireContext());r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(13),dp(10),dp(13),dp(10));r.setBackgroundResource(selected(e)?R.drawable.bg_skin_slot_selected:R.drawable.bg_cs_client_transparent);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(70));lp.bottomMargin=dp(7);r.setLayoutParams(lp);TextView t=new TextView(requireContext());t.setText((selected(e)?"✓  ":"○  ")+e.title);t.setTextColor(0xffffffff);t.setTextSize(12);t.setTypeface(null,1);TextView d=new TextView(requireContext());d.setText(e.description);d.setTextColor(0xff898b92);d.setTextSize(9);d.setMaxLines(2);r.addView(t);r.addView(d);r.setOnClickListener(v->{if(pack)CsClientSelection.modpack=selected(e)?null:e;else CsClientSelection.toggleMod(e);load(search.getText().toString());});UiMotion.pressFeedback(r);return r;}private boolean selected(CsClientCatalog.ProjectEntry e){return pack?CsClientSelection.modpack!=null&&CsClientSelection.modpack.id.equals(e.id):CsClientSelection.contains(e.id);}private void back(){requireActivity().getSupportFragmentManager().popBackStack();}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}}
